/**
 * @file        build-bravojs-bundle.js
 * @description Flattens ffmpeg-wasm/dcp-transcode-glue.js + ffmpeg-wasm/dcp-transcode.wasm
 *              into one file wrapped in bravojs's module format (module.declare),
 *              the format DCP's package publisher expects -- see
 *              docs/patching-wasm-libraries-for-dcp.html in the Edequity
 *              repo (the same pattern used for duckdbwasm, fftw3wasm-v3,
 *              cfitsio4wasm, sofia2wasm).
 *
 *              Unlike those, dcp-transcode's build.sh does NOT pass
 *              -sSINGLE_FILE=1 to emcc, so the wasm binary is its own
 *              10MB+ file rather than already base64-embedded in the glue.
 *              This script embeds it by hand instead, and wraps
 *              createFfmpegModule so it always supplies its own
 *              instantiateWasm from the embedded bytes -- the same
 *              technique app.js's own DCP work function already uses
 *              (ffmpeg-dcp/app.js, runFleetRace()'s workFunction) to avoid
 *              the glue's default fetch()-based loader, which DCP's worker
 *              sandbox rejects outright (EPERM_ORIGIN blocks fetch(),
 *              including data: URIs -- see wasm-in-dcp-workers.html in the
 *              Edequity repo). Callers of the published package therefore
 *              never need to supply instantiateWasm themselves.
 *
 * @usage       node build-bravojs-bundle.js
 *              (run after ../build.sh; writes ./ffmpeg-wasm.js)
 */
'use strict';

const fs = require('fs');
const path = require('path');

const SRC_DIR = path.join(__dirname, '..', 'ffmpeg-wasm');

const glueSrc = fs.readFileSync(path.join(SRC_DIR, 'dcp-transcode-glue.js'), 'utf8');
const wasmBytes = fs.readFileSync(path.join(SRC_DIR, 'dcp-transcode.wasm'));
const wasmBase64 = wasmBytes.toString('base64');

const bundle = `/**
 * @file        ffmpeg-wasm.js (published bundle)
 * @description Published-package form of ffmpeg-wasm/dcp-transcode-glue.js +
 *              ffmpeg-wasm/dcp-transcode.wasm (base64-embedded by hand, since
 *              this build isn't -sSINGLE_FILE=1), wrapped in bravojs's module
 *              format (module.declare) per the DCP package publishing
 *              convention -- see docs/patching-wasm-libraries-for-dcp.html
 *              in the Edequity repo.
 *              Generated by build-bravojs-bundle.js; do not hand-edit --
 *              edit ../app.js / rerun ../build.sh + this script instead.
 *
 * @usage       job.requires(['ffmpeg-wasm-test/ffmpeg-wasm.js']);
 *              // inside the work function:
 *              const { createFfmpegModule } = require('ffmpeg-wasm.js');  // bare filename, no ./
 *              const Module = await createFfmpegModule();
 *              // Module.FS / Module.ccall exactly as in app.js's sliceVideo() etc.
 */
module.declare([], function (require, exports, module) {
  // ---- dcp-transcode-glue.js (Emscripten build of ffmpeg + libopenh264 +
  // x264 + SVT-AV1 + x265), verbatim, evaluated as a CommonJS module body ----
  var moduleShim = { exports: {} };
  (function (module, exports) {
${glueSrc}
  })(moduleShim, moduleShim.exports);
  var createFfmpegModuleRaw = moduleShim.exports;

  // ---- dcp-transcode.wasm, base64-embedded (no -sSINGLE_FILE=1 in build.sh,
  // so this is done by hand here instead) ----
  var wasmBase64 = "${wasmBase64}";

  // Wrap createFfmpegModuleRaw so callers never need to supply
  // instantiateWasm themselves: decode once per call, instantiate directly
  // from the embedded bytes, never touching the glue's own fetch()-based
  // loader.
  function createFfmpegModule(moduleArg) {
    moduleArg = moduleArg || {};
    if (!moduleArg.instantiateWasm) {
      var wasmBytes = Uint8Array.from(atob(wasmBase64), function (c) { return c.charCodeAt(0); });
      moduleArg.instantiateWasm = function (imports, successCallback) {
        WebAssembly.instantiate(wasmBytes, imports).then(function (result) { successCallback(result.instance); });
      };
    }
    return createFfmpegModuleRaw(moduleArg);
  }

  exports.createFfmpegModule = createFfmpegModule;
  exports.default = createFfmpegModule;
});
`;

const outPath = path.join(__dirname, 'ffmpeg-wasm.js');
fs.writeFileSync(outPath, bundle);
console.log(`wrote ${outPath} (${(bundle.length / (1024 * 1024)).toFixed(1)} MB)`);
